<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('inventory.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try{db()->beginTransaction(); $to=(int)$_POST['to_branch_id']; if($to===$bid) throw new RuntimeException('Choose a different destination branch.'); $no=next_code('TRF','stock_transfers','transfer_no'); q('INSERT INTO stock_transfers(transfer_no,from_branch_id,to_branch_id,status,transfer_date,notes,created_by,received_by,created_at) VALUES(?,?,?,"received",?,?,?, ?,NOW())',[$no,$bid,$to,$_POST['transfer_date'],trim($_POST['notes']??''),$_SESSION['user_id'],$_SESSION['user_id']]); $tid=(int)db()->lastInsertId(); foreach($_POST['product_id']??[] as $i=>$pid){$pid=(int)$pid;$qty=(float)($_POST['quantity'][$i]??0); if($pid&&$qty>0){ if(stock_balance($bid,$pid)<$qty) throw new RuntimeException('Insufficient stock for transfer.'); q('INSERT INTO stock_transfer_items(transfer_id,product_id,quantity) VALUES(?,?,?)',[$tid,$pid,$qty]); stock_move($bid,$pid,-$qty,'transfer_out','transfer',$tid,'Transfer to branch '.$to); stock_move($to,$pid,$qty,'transfer_in','transfer',$tid,'Transfer from branch '.$bid); }} audit('create','stock_transfers',$tid); db()->commit(); flash('success','Stock transferred.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/stock_transfers.php');}
$branches=all('SELECT id,name FROM branches WHERE status="active" ORDER BY name'); $rows=all('SELECT t.*,fb.name from_branch,tb.name to_branch FROM stock_transfers t JOIN branches fb ON fb.id=t.from_branch_id JOIN branches tb ON tb.id=t.to_branch_id WHERE t.from_branch_id=? OR t.to_branch_id=? ORDER BY t.id DESC LIMIT 100',[$bid,$bid]); $title='Branch Stock Transfers'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><h2>New Transfer</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>To Branch</label><select name="to_branch_id" required><?php foreach($branches as $b): if((int)$b['id']===$bid)continue;?><option value="<?=e($b['id'])?>"><?=e($b['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Date</label><input type="date" name="transfer_date" value="<?=e(today())?>"></div><div class="form-group full"><label>Notes</label><input name="notes"></div></div><div id="lines"><div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity[]" placeholder="Qty"><span></span><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div></div><button type="button" class="btn secondary" onclick="addLine()">+ Add Product</button> <button class="btn">Transfer</button></form></section><script>function addLine(){document.querySelector('#lines').insertAdjacentHTML('beforeend',`<div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity[]" placeholder="Qty"><span></span><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div>`)}</script><div class="table-wrap"><table><thead><tr><th>Date</th><th>No.</th><th>From</th><th>To</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transfer_date'])?></td><td><?=e($r['transfer_no'])?></td><td><?=e($r['from_branch'])?></td><td><?=e($r['to_branch'])?></td><td><?=e($r['status'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>